    document.addEventListener('DOMContentLoaded', () => {
        const dataContainer = document.querySelector('.status-panel-data-container');
        const worldStatusBar = document.getElementById('worldStatusBar');
        const characterContainer = document.getElementById('characterCardsContainer');

        if (!dataContainer || !characterContainer || !worldStatusBar) return;

        const rawData = dataContainer.textContent.trim();
        if (!rawData) return;

        function parseData(text) {
            const data = { world: {}, characters: [] };

            const worldMatch = text.match(/\[世界状态\]([\s\S]*?)\[\/世界状态\]/);
