            let match;
            while ((match = characterRegex.exec(text)) !== null) {
                const name = match[1];
                const content = match[2];

                const character = { name, 服装: {}, 状态: { 脚部状态: {}, 内心独白: '' } };

                const clothingMatch = content.match(/服装:([\s\S]*?)(?=状态:|$)/);
                const statusBlockMatch = content.match(/状态:([\s\S]*?)(?=内心独白:|$)/);
