                        const [key, value] = line.trim().split(/:(.*)/s);
                        if (key && value !== undefined) character.服装[key.trim()] = value.trim();
                    });
                }

                if (statusBlockMatch) {
                    const footStatusMatch = statusBlockMatch[1].match(/脚部状态:([\s\S]*)/);
                    if (footStatusMatch) {
                        footStatusMatch[1].trim().split('\n').forEach(line => {
                            const trimmedLine = line.trim();
                            if (!trimmedLine || !trimmedLine.startsWith('-')) return;
                            const [key, value] = trimmedLine.replace(/^-/, '').trim().split(/:(.*)/s);
                            if (key && value !== undefined) {
                                character.状态.脚部状态[key.trim()] = value.trim().replace(/\[\{\{|\}\}\]/g, '');
                            }
                        });
                    }
                }

                if (monologueMatch) {
                    character.状态.内心独白 = monologueMatch[1].trim();
                }

                data.characters.push(character);
            }
            return data;
        }

        const parsedData = parseData(rawData);

        if (Object.keys(parsedData.world).length > 0) {
            worldStatusBar.style.display = 'flex';
            worldStatusBar.innerHTML = Object.entries(parsedData.world)
                .map(([key, value]) => `<div class="world-status-item"><strong>${key}:</strong> ${value || '未知'}</div>`)
                .join('');
        }

        // Updated rendering logic to use <details> and <summary>
