                        </ul>
                    </div>
                    <div class="status-section">
                        <h3>内心独白</h3>
                        <div class="inner-monologue">${status.内心独白 || '...'}</div>
                    </div>
                </div>
            </details>
            `;
        }).join('');
    });
    </script>
